import '@servicenow/sdk/global'
import { action, Flow, wfa } from '@servicenow/sdk/automation'
import { trigger } from '@servicenow/sdk/automation'

// -----------------------------------------------------------------------------
// Flow definition (one trigger + one Action instance in body)
// -----------------------------------------------------------------------------
Flow(
    {
        $id: Now.ID['flow_with_action'],
        name: 'Flow - Calls Action',
        description: 'Flow that executes a single Action instance',
        runAs: 'system',
        runWithRoles: [],
        flowPriority: 'MEDIUM',
    },
    wfa.trigger(
        trigger.record.created,
        { $id: Now.ID['trg_echo'], annotation: 'Monitor CMDB CI creation' },
        {
            table: 'cmdb_ci',
            condition: '',
            run_on_extended: 'false',
            run_flow_in: 'background',
            run_when_user_list: [],
            run_when_setting: 'both',
            run_when_user_setting: 'any',
        }
    ),
    (_trigger) => {
        wfa.action(
            action.core.log,
            { $id: Now.ID['act_echo_instance'] },
            {
                log_level: 'info',
                log_message: 'Hello world',
            }
        )
    }
)
